UPDATE "facets" SET "description" = CASE "slug"
  WHEN 'typescript' THEN 'Type-safe tools and frameworks for modern JavaScript teams.'
  WHEN 'javascript' THEN 'Projects built for the web platform and JavaScript runtime ecosystem.'
  WHEN 'dart' THEN 'Dart tools for cross-platform application development.'
  WHEN 'go' THEN 'Go projects for compact, operationally direct backend systems.'
  WHEN 'python' THEN 'Python tools spanning backend services, data, and AI applications.'
  WHEN 'infrastructure-as-code' THEN 'Declarative tools for provisioning and governing infrastructure.'
  WHEN 'containers' THEN 'Tools for packaging, scheduling, and operating container workloads.'
  WHEN 'opentelemetry' THEN 'Vendor-neutral instrumentation and telemetry pipelines.'
  WHEN 'dashboards' THEN 'Operational visualization and investigation surfaces.'
  WHEN 'ai-applications' THEN 'Frameworks and SDKs for production AI application work.'
  WHEN 'local-models' THEN 'Runtimes and tools for running models on developer-owned hardware.'
  ELSE "description"
END;
--> statement-breakpoint
WITH assignments("project_slug", "facet_slug") AS (VALUES
