  ('opentofu','infrastructure-as-code'), ('kubernetes','containers'),
  ('opentelemetry','opentelemetry'), ('grafana','dashboards'), ('grafana','opentelemetry'),
  ('langchain','python'), ('langchain','typescript'), ('langchain','ai-applications'),
  ('ollama','local-models'), ('ollama','ai-applications')
)
INSERT INTO "project_facets" ("project_id", "facet_id")
SELECT projects."id", facets."id" FROM assignments
JOIN projects ON projects."slug" = assignments."project_slug"
JOIN facets ON facets."slug" = assignments."facet_slug"
ON CONFLICT DO NOTHING;
