('nextjs','https://nextjs.org','https://nextjs.org/docs','https://github.com/vercel/next.js'),('vue','https://vuejs.org','https://vuejs.org/guide/','https://github.com/vuejs/core'),('astro','https://astro.build','https://docs.astro.build','https://github.com/withastro/astro'),('tailwind-css','https://tailwindcss.com','https://tailwindcss.com/docs','https://github.com/tailwindlabs/tailwindcss'),('better-auth','https://www.better-auth.com','https://www.better-auth.com/docs','https://github.com/better-auth/better-auth'),('deno','https://deno.com','https://docs.deno.com','https://github.com/denoland/deno'),('bun','https://bun.com','https://bun.com/docs','https://github.com/oven-sh/bun'),('django','https://www.djangoproject.com','https://docs.djangoproject.com','https://github.com/django/django'),('postgresql','https://www.postgresql.org','https://www.postgresql.org/docs/','https://github.com/postgres/postgres'),('react-native','https://reactnative.dev','https://reactnative.dev/docs/getting-started','https://github.com/facebook/react-native'),('kotlin-multiplatform','https://kotlinlang.org/docs/multiplatform.html','https://kotlinlang.org/docs/multiplatform-get-started.html','https://github.com/JetBrains/kotlin'),('capacitor','https://capacitorjs.com','https://capacitorjs.com/docs','https://github.com/ionic-team/capacitor'),('tauri','https://tauri.app','https://tauri.app/start/','https://github.com/tauri-apps/tauri'),('docker','https://www.docker.com','https://docs.docker.com/engine/','https://github.com/moby/moby'),('pulumi','https://www.pulumi.com','https://www.pulumi.com/docs/','https://github.com/pulumi/pulumi'),('ansible','https://www.ansible.com','https://docs.ansible.com','https://github.com/ansible/ansible'),('argo-cd','https://argo-cd.readthedocs.io','https://argo-cd.readthedocs.io/en/stable/','https://github.com/argoproj/argo-cd'),('vercel','https://vercel.com','https://vercel.com/docs','https://github.com/vercel/vercel'),('prometheus','https://prometheus.io','https://prometheus.io/docs/','https://github.com/prometheus/prometheus'),('jaeger','https://www.jaegertracing.io','https://www.jaegertracing.io/docs/','https://github.com/jaegertracing/jaeger'),('signoz','https://signoz.io','https://signoz.io/docs/','https://github.com/SigNoz/signoz'),('loki','https://grafana.com/oss/loki/','https://grafana.com/docs/loki/latest/','https://github.com/grafana/loki'),('sentry','https://sentry.io','https://docs.sentry.io','https://github.com/getsentry/sentry'),('ai-sdk','https://ai-sdk.dev','https://ai-sdk.dev/docs','https://github.com/vercel/ai'),('llamaindex','https://www.llamaindex.ai','https://docs.llamaindex.ai','https://github.com/run-llama/llama_index'),('vllm','https://vllm.ai','https://docs.vllm.ai','https://github.com/vllm-project/vllm'),('continue','https://continue.dev','https://docs.continue.dev','https://github.com/continuedev/continue')) v)
, links AS (SELECT "slug",'website' kind,"website" url FROM details UNION ALL SELECT "slug",'documentation',"docs" FROM details UNION ALL SELECT "slug",'repository',"repo" FROM details)
INSERT INTO "project_links" ("project_id","kind","url","last_successful_check_at") SELECT projects."id",links.kind,links.url,'2026-09-04T00:00:00Z' FROM links JOIN projects USING ("slug") ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "project_sources" ("project_id","claim","source_type","url","checked_at","checked_by") SELECT projects."id",'Official documentation, repository, license, and product facts','maintainer',project_links."url",'2026-09-04T00:00:00Z','HowToBuild.dev editorial' FROM projects JOIN project_links ON project_links."project_id"=projects."id" AND project_links."kind"='repository' WHERE projects."published_at"='2026-09-04T00:00:00Z' AND NOT EXISTS (SELECT 1 FROM project_sources ps WHERE ps."project_id"=projects."id");
--> statement-breakpoint
WITH assignments("project_slug","facet_slug") AS (VALUES ('nextjs','typescript'),('vue','typescript'),('astro','typescript'),('tailwind-css','javascript'),('better-auth','typescript'),('deno','typescript'),('bun','typescript'),('django','python'),('postgresql','typescript'),('react-native','typescript'),('kotlin-multiplatform','kotlin'),('capacitor','typescript'),('tauri','rust'),('docker','containers'),('pulumi','infrastructure-as-code'),('ansible','infrastructure-as-code'),('argo-cd','ci-cd'),('vercel','ci-cd'),('prometheus','opentelemetry'),('jaeger','opentelemetry'),('signoz','opentelemetry'),('loki','dashboards'),('sentry','error-tracking'),('ai-sdk','ai-sdks'),('llamaindex','ai-applications'),('vllm','model-infrastructure'),('continue','coding-agents')) INSERT INTO "project_facets" SELECT projects."id",facets."id" FROM assignments JOIN projects ON projects."slug"=assignments."project_slug" JOIN facets ON facets."slug"=assignments."facet_slug" ON CONFLICT DO NOTHING;
--> statement-breakpoint
WITH aliases("project_slug","alias") AS (VALUES ('better-auth','auth'),('better-auth','authentication'),('fastify','typescript backend'),('hono','typescript backend'),('postgresql','postgres'),('vercel','free hosting'),('continue','ai coding'),('continue','coding agent'),('pulumi','iac'),('argo-cd','gitops'),('react-native','react native'),('ai-sdk','vercel ai sdk'),('vllm','model serving')) INSERT INTO "search_aliases" ("project_id","alias","normalized_alias") SELECT projects."id",aliases."alias",lower(aliases."alias") FROM aliases JOIN projects ON projects."slug"=aliases."project_slug" ON CONFLICT DO NOTHING;
--> statement-breakpoint
WITH details("slug","owner","name") AS (VALUES ('nextjs','vercel','next.js'),('vue','vuejs','core'),('astro','withastro','astro'),('tailwind-css','tailwindlabs','tailwindcss'),('better-auth','better-auth','better-auth'),('deno','denoland','deno'),('bun','oven-sh','bun'),('django','django','django'),('postgresql','postgres','postgres'),('react-native','facebook','react-native'),('kotlin-multiplatform','JetBrains','kotlin'),('capacitor','ionic-team','capacitor'),('tauri','tauri-apps','tauri'),('docker','moby','moby'),('pulumi','pulumi','pulumi'),('ansible','ansible','ansible'),('argo-cd','argoproj','argo-cd'),('vercel','vercel','vercel'),('prometheus','prometheus','prometheus'),('jaeger','jaegertracing','jaeger'),('signoz','SigNoz','signoz'),('loki','grafana','loki'),('sentry','getsentry','sentry'),('ai-sdk','vercel','ai'),('llamaindex','run-llama','llama_index'),('vllm','vllm-project','vllm'),('continue','continuedev','continue')), inserted AS (INSERT INTO "repositories" ("github_node_id","owner","name") SELECT 'pending:'||lower("owner")||'/'||lower("name"),"owner","name" FROM details ON CONFLICT ("owner","name") DO UPDATE SET "owner"=EXCLUDED."owner" RETURNING "id","owner","name") INSERT INTO "project_repositories" SELECT projects."id",inserted."id",true FROM details JOIN projects ON projects."slug"=details."slug" JOIN inserted ON lower(inserted."owner")=lower(details."owner") AND lower(inserted."name")=lower(details."name") ON CONFLICT DO NOTHING;
--> statement-breakpoint
WITH aliases("project_slug", "alias") AS (VALUES
  ('react','react.js'), ('svelte','sveltekit'), ('fastify','node api'),
  ('hono','edge api'), ('flutter','cross platform mobile'), ('expo','react native'),
  ('opentofu','terraform alternative'), ('opentofu','iac'), ('kubernetes','k8s'),
  ('opentelemetry','otel'), ('grafana','monitoring dashboards'),
  ('langchain','llm framework'), ('langchain','ai application framework'),
  ('ollama','local llm')
)
INSERT INTO "search_aliases" ("project_id", "alias", "normalized_alias")
SELECT projects."id", aliases."alias", lower(aliases."alias") FROM aliases
JOIN projects ON projects."slug" = aliases."project_slug"
ON CONFLICT DO NOTHING;
--> statement-breakpoint
WITH coordinates("project_slug", "owner", "name") AS (VALUES
  ('react','facebook','react'), ('svelte','sveltejs','svelte'),
  ('fastify','fastify','fastify'), ('hono','honojs','hono'),
  ('flutter','flutter','flutter'), ('expo','expo','expo'),
  ('opentofu','opentofu','opentofu'), ('kubernetes','kubernetes','kubernetes'),
  ('opentelemetry','open-telemetry','opentelemetry-specification'),
  ('grafana','grafana','grafana'), ('langchain','langchain-ai','langchain'),
  ('ollama','ollama','ollama')
), inserted AS (
  INSERT INTO "repositories" ("github_node_id", "owner", "name")
  SELECT 'pending:' || lower("owner") || '/' || lower("name"), "owner", "name" FROM coordinates
  ON CONFLICT ("owner", "name") DO UPDATE SET "owner" = EXCLUDED."owner"
  RETURNING "id", "owner", "name"
)
INSERT INTO "project_repositories" ("project_id", "repository_id", "is_default")
SELECT projects."id", inserted."id", true FROM coordinates
JOIN projects ON projects."slug" = coordinates."project_slug"
JOIN inserted ON lower(inserted."owner") = lower(coordinates."owner") AND lower(inserted."name") = lower(coordinates."name")
ON CONFLICT DO NOTHING;
